(()=>{
'use strict';
const races={Humano:{skin:'#d9a27d',hair:'#68452e',scale:1},Elfo:{skin:'#e8c29d',hair:'#9b7655',scale:1,ears:'point'},Enano:{skin:'#c68d62',hair:'#493328',scale:.9,beard:true},Orco:{skin:'#819853',hair:'#283329',scale:1.08,ears:'point',tusks:true},Mediano:{skin:'#d4a177',hair:'#5d3c28',scale:.78},Gnomo:{skin:'#d0a17f',hair:'#734934',scale:.82,ears:'point'},Semielfo:{skin:'#e1b68f',hair:'#5a3c2c',scale:1,ears:'point'},Semiorco:{skin:'#a08562',hair:'#293329',scale:1.04,ears:'point',tusks:true}};
const classes={Guerrero:{body:'#68452f',accent:'#d9b56c'},Pícaro:{body:'#1e3732',accent:'#8fc8b1'},Mago:{body:'#403765',accent:'#b9aaf4'}};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function source(character={},options={}){
 const race=races[character.race]||races.Humano,cls=classes[character.class]||classes.Guerrero,gender=character.gender||'No binario',cape=Boolean(options.cape),scale=race.scale||1;
 const ears=race.ears==='point'?`<path d="M52 51 L27 32 L42 63 M108 51 L133 32 L118 63" fill="${race.skin}" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/>`:`<circle cx="48" cy="51" r="7" fill="${race.skin}" stroke="#241b18" stroke-width="4"/><circle cx="112" cy="51" r="7" fill="${race.skin}" stroke="#241b18" stroke-width="4"/>`;
 const hair=gender==='Mujer'?`<path d="M49 47 Q80 15 111 47 L117 94 Q106 110 98 91 L92 66 Q80 75 68 66 L62 91 Q54 109 43 94 Z" fill="${race.hair}" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/>`:`<path d="M48 48 Q80 12 112 48 L104 62 L93 39 L81 56 L69 38 L56 63 Z" fill="${race.hair}" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/>`;
 const genderHair=gender==='Mujer'?`<path d="M50 61 Q34 105 55 126 M110 61 Q126 105 105 126" fill="none" stroke="${race.hair}" stroke-width="11" stroke-linecap="round"/>`:'';
 const beard=race.beard?`<path d="M57 66 Q80 91 103 66 L98 91 L80 106 L62 91 Z" fill="${race.hair}" stroke="#241b18" stroke-width="4"/>`:'';
 const tusks=race.tusks?`<path d="M67 69 Q68 82 74 72 M93 69 Q92 82 86 72" fill="none" stroke="#f4dfad" stroke-width="5" stroke-linecap="round"/>`:'';
 const cloak=cape?'#755c39':cls.body==='#403765'?'#2a2350':'#233b31';
 const body=character.class==='Mago'?`<path d="M53 82 Q80 70 107 82 L124 162 Q80 180 36 162 Z" fill="${cls.body}" stroke="#241b18" stroke-width="5"/><path d="M80 80 L80 169" stroke="${cls.accent}" stroke-width="6"/>`:`<path d="M53 82 Q80 72 107 82 L111 137 Q80 150 49 137 Z" fill="${cls.body}" stroke="#241b18" stroke-width="5"/><path d="M80 79 L80 140" stroke="${cls.accent}" stroke-width="6"/>`;
 const arms=`<path d="M55 88 L35 119 L48 127 L66 103 M105 88 L125 119 L112 127 L94 103" fill="${cls.body}" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/>`;
 const legs=`<path d="M56 133 L76 137 L70 171 L55 184 L43 177 Z M84 137 L104 133 L117 177 L105 184 L90 171 Z" fill="#332b28" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/><path d="M47 176 L70 171 L76 185 L45 190 Z M90 171 L113 176 L115 190 L84 185 Z" fill="#5a3928" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/>`;
 const weapon=character.class==='Mago'?`<path d="M124 93 L137 176" stroke="${cls.accent}" stroke-width="5" stroke-linecap="round"/><circle cx="123" cy="88" r="8" fill="${cls.accent}" stroke="#fff0c5" stroke-width="3"/>`:character.class==='Pícaro'?`<path d="M119 107 L143 136" stroke="${cls.accent}" stroke-width="5" stroke-linecap="round"/><path d="M141 133 L148 142 L136 138 Z" fill="#dfe9d9" stroke="#241b18" stroke-width="3"/>`:`<path d="M126 85 L145 133" stroke="#e9d8a0" stroke-width="5" stroke-linecap="round"/><path d="M116 93 L132 87" stroke="#6e4d31" stroke-width="5" stroke-linecap="round"/><path d="M134 133 L148 142" stroke="#e9d8a0" stroke-width="4" stroke-linecap="round"/>`;
 const classHead=character.class==='Mago'?`<path d="M48 36 L112 36 L80 5 Z" fill="${cls.accent}" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/><path d="M57 37 Q80 46 103 37" fill="none" stroke="#fff0c5" stroke-width="3"/>`:character.class==='Pícaro'?`<path d="M43 47 Q80 17 117 47 L108 61 Q80 50 52 61 Z" fill="#142723" stroke="#241b18" stroke-width="5"/>`:'';
 const badge=character.subclass==='Berserker'?'✹':character.subclass==='Sombra'?'◈':character.subclass==='Explorador'?'✧':character.subclass==='Arcanista'?'✧':character.subclass==='Tejedor'?'◌':'✦';
 const neutral=gender==='No binario'?`<circle cx="80" cy="51" r="39" fill="none" stroke="${cls.accent}" stroke-width="2" stroke-dasharray="4 5" opacity=".75"/>`:'';
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="200" viewBox="0 0 160 200" role="img" aria-label="Personaje jugable ${esc(character.race||'Humano')} ${esc(character.class||'Guerrero')} ${esc(gender)}"><defs><linearGradient id="cloak" x1="0" x2="1"><stop stop-color="#13251e"/><stop offset=".5" stop-color="${cloak}"/><stop offset="1" stop-color="#0e1c18"/></linearGradient><linearGradient id="metal" x1="0" x2="1"><stop stop-color="#fff0c5"/><stop offset=".5" stop-color="${cls.accent}"/><stop offset="1" stop-color="#765339"/></linearGradient></defs><g transform="translate(80 0) scale(${scale}) translate(-80 0)"><ellipse cx="80" cy="191" rx="36" ry="7" fill="#020806" opacity=".55"/><path d="M38 91 Q80 68 122 91 L134 166 Q80 181 26 166 Z" fill="url(#cloak)" stroke="#241b18" stroke-width="5" stroke-linejoin="round"/><path d="M54 139 L80 147 L106 139" fill="none" stroke="${cape?'#f0cf7a':cls.accent}" stroke-width="4"/>${legs}${arms}${body}<circle cx="80" cy="51" r="31" fill="${race.skin}" stroke="#241b18" stroke-width="5"/>${ears}${hair}${genderHair}${beard}${tusks}<path d="M65 55 Q80 64 95 55" fill="none" stroke="#241b18" stroke-width="3" stroke-linecap="round"/><circle cx="68" cy="50" r="4" fill="#15211e"/><circle cx="92" cy="50" r="4" fill="#15211e"/>${neutral}${classHead}${weapon}<circle cx="80" cy="104" r="11" fill="url(#metal)" stroke="#241b18" stroke-width="4"/><text x="80" y="110" text-anchor="middle" fill="#fff8dc" font-family="Georgia,serif" font-size="12">${badge}</text></g></svg>`;
 return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}
window.CenizasAvatar={source};
})();
